function csvUrl({ id, gid }) {
  return `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&gid=${gid}`;
}

async function fetchCsvOnce(sheet) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(csvUrl(sheet), { signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status} при загрузке листа ${sheet.id}#${sheet.gid}`);
    const text = await res.text();
    if (/<html/i.test(text.slice(0, 200))) {
      throw new Error('Google вернул HTML вместо CSV — вероятно, таблица закрыта от публичного доступа');
    }
    return parseCsv(text);
  } finally {
    clearTimeout(timer);
  }
}

// Сеть до Google из некоторых хостингов бывает медленной/нестабильной —
// даём несколько попыток с увеличивающейся паузой, прежде чем сдаться.
async function fetchCsv(sheet, attempts = 3) {
  let lastErr;
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fetchCsvOnce(sheet);
    } catch (e) {
      lastErr = e;
      console.warn(`Попытка ${i}/${attempts} загрузки листа ${sheet.id}#${sheet.gid} не удалась: ${e.message}`);
      if (i < attempts) await new Promise((r) => setTimeout(r, 2000 * i));
    }
  }
  throw lastErr;
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      row.push(field); field = '';
    } else if (c === '\r') {
      // skip
    } else if (c === '\n') {
      row.push(field); rows.push(row); row = []; field = '';
    } else {
      field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

// Full workbook export uses sheet names and preserves date headers. No fixed gid/column calendar.
const MAX_BOOK_BYTES = 50 * 1024 * 1024;
async function fetchWorkbook() {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 90000);
  try {
    const response = await fetch(`https://docs.google.com/spreadsheets/d/${encodeURIComponent(MAP_ID)}/export?format=xlsx`, { signal: controller.signal });
    if (!response.ok) throw new Error(`Google Sheets: HTTP ${response.status}`);
    const chunks = []; let size = 0;
    for await (const chunk of response.body) {
      size += chunk.length;
      if (size > MAX_BOOK_BYTES) { controller.abort(); throw new Error('Книга превышает лимит 50 МБ'); }
      chunks.push(chunk);
    }
    const buffer = Buffer.concat(chunks);
    if (buffer[0] !== 0x50 || buffer[1] !== 0x4b) throw new Error('Google не вернул Excel-книгу. Проверьте доступ сервера к таблице.');
    return buffer;
  } finally { clearTimeout(timer); }
}

export async function applyUploadedWorkbook(buffer, fileName) {
  if (refreshInFlight) throw new Error('Идёт обновление Google Sheets. Дождитесь его завершения перед загрузкой файла.');
  if (uploadInFlight) throw new Error('Другая книга уже загружается.');
  uploadInFlight = true;
  try {
    const result = await importWorkbook(buffer, { source: 'upload', sourceFile: fileName });
    const base = memCache || DEFAULT_DATA;
    if (result.calculatorOnly) {
      result.data = { ...base, calc: result.data.calc, calcSource: result.data.calcSource };
    } else if (!result.data.calc) {
      result.data.calc = base.calc;
      result.data.calcSource = base.calcSource || { source: 'fallback', loadedAt: null };
      result.data.analytics.diagnostics.push({ code: 'external_calculator', sheet: 'Калькулятор', message: 'Калькулятор по чекам — отдельный источник. Его период и город указаны в разделе.' });
    }
    memCache = result.data;
    saveDiskCache(memCache);
    return { ...result, fileName };
  } finally { uploadInFlight = false; }
}

async function fetchLive() {
  const [book, calcResult] = await Promise.allSettled([fetchWorkbook(), fetchCsv(SHEET_CALC, 1)]);
  if (book.status !== 'fulfilled') throw book.reason;
  const result = await importWorkbook(book.value, { source: 'live' });
  if (result.calculatorOnly) throw new Error('В основной Google-книге найден только калькулятор. Проверьте GOOGLE_SHEET_ID.');
  const base = memCache || DEFAULT_DATA;
  if (calcResult.status === 'fulfilled') {
    const calc = buildCalcData(calcResult.value);
    if (calc.city !== '—' && calc.buckets.length) {
      result.data.calc = calc;
      result.data.calcSource = { source: 'live', loadedAt: Date.now() };
    } else {
      result.data.calc = base.calc;
      result.data.calcSource = base.calcSource || { source: 'fallback', loadedAt: null };
      result.data.analytics.diagnostics.push({ code: 'calculator_schema', sheet: 'Калькулятор', message: 'Структура калькулятора изменилась. Сохранён предыдущий расчёт; основная книга обновлена.' });
    }
  } else {
    result.data.calc = base.calc;
    result.data.calcSource = base.calcSource || { source: 'fallback', loadedAt: null };
    result.data.analytics.diagnostics.push({ code: 'calculator_stale', sheet: 'Калькулятор', message: 'Калькулятор не обновился: сохранён предыдущий набор. Основная книга обновлена.' });
  }
  return result.data;
}

function loadDiskCache() {
  try {
    if (!fs.existsSync(CACHE_FILE)) return null;
    const raw = fs.readFileSync(CACHE_FILE, 'utf8');
    const data = JSON.parse(raw);
    return data.schemaVersion === SCHEMA_VERSION ? data : null;
  } catch {
    return null;
  }
}
function saveDiskCache(data) {
  try {
    fs.mkdirSync(path.dirname(CACHE_FILE), { recursive: true });
    const tmp = CACHE_FILE + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(data), 'utf8');
    fs.renameSync(tmp, CACHE_FILE);
  } catch (e) {
    console.warn('Не удалось сохранить кэш на диск:', e.message);
  }
}

let memCache = null;
let refreshInFlight = null;
let uploadInFlight = false;

export async function refreshData() {
  if (uploadInFlight) throw new Error('Идёт импорт Excel. Дождитесь его завершения.');
  if (refreshInFlight) return refreshInFlight; // не дублируем параллельные запросы
  refreshInFlight = (async () => {
    const data = await fetchLive();
    memCache = data;
    saveDiskCache(data);
    return data;
  })();
  try {
    return await refreshInFlight;
  } finally {
    refreshInFlight = null;
  }
}

export async function getData() {
  if (memCache) {
    if (Date.now() - memCache.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Фоновое обновление не удалось:', e.message));
    }
    return memCache;
  }
  const disk = loadDiskCache();
  if (disk) {
    memCache = disk;
    if (Date.now() - disk.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Фоновое обновление не удалось:', e.message));
    }
    return memCache;
  }
  try {
    return await refreshData();
  } catch (e) {
    console.warn('Первая загрузка из Google Sheets не удалась, используем резервный снимок:', e.message);
    memCache = { ...DEFAULT_DATA, generatedAt: null, source: 'fallback' };
    return memCache;
  }
}

// Проверяем раз в час, обновляем, если кэшу больше 24 часов —
// так дашборд освежается сам, даже если на сайт никто не заходит.
export function startScheduler() {
  setInterval(() => {
    if (!memCache || Date.now() - memCache.generatedAt > CACHE_TTL_MS) {
      refreshData().catch((e) => console.warn('Плановое обновление не удалось:', e.message));
    }
  }, 60 * 60 * 1000);
}

